function Avatar({ member, size = "md", avatarUrl }: { member: Member | { initials: string; color: string }; size?: "sm" | "md" | "lg"; avatarUrl?: string }) {
  return avatarUrl ? <img className={`avatar avatar-${size}`} src={avatarUrl} alt={member.initials} /> : <span className={`avatar avatar-${size}`} style={{ background: member.color }}>{member.initials}</span>;
}

function App() {
  const [showLanding, setShowLanding] = useState(true);
  const [showAuth, setShowAuth] = useState(false);
  const [authMode, setAuthMode] = useState<"signin" | "signup">("signin");
  const [authUser, setAuthUser] = useState<AuthUser | null>(null);
  const [activeView, setActiveView] = useState<View>("overview");
  const [activeGroup, setActiveGroup] = useState(groups[0]);
  const [showGroupMenu, setShowGroupMenu] = useState(false);
  const [expenses, setExpenses] = useState(initialExpenses);
  const [activity, setActivity] = useState(initialActivity);
  const [chat, setChat] = useState(initialChat);
  const [privateChats, setPrivateChats] = useState<Record<string, ChatMessage[]>>({ nabil: [{ id: "dm-1", senderId: "nabil", member: "Nabil", initials: "NB", message: "Bro, I uploaded the ride receipt.", time: "09:42", color: "#99b8ff" }] });
  const [conversation, setConversation] = useState<Conversation>({ id: "group", kind: "group", title: "Dhaka trip", subtitle: "8 members · messages become actions", unread: 3, lastMessage: "I'm in. Add it to the trip budget?", accent: "#b7f36b" });
  const [showExpense, setShowExpense] = useState(false);
  const [showPalette, setShowPalette] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfile, setShowProfile] = useState<Member | null>(null);
  const [theme, setTheme] = useState<"dark" | "light">("dark");
  const [chatTheme, setChatTheme] = useState("default");
  const [query, setQuery] = useState("");
  const [toast, setToast] = useState("");
  const [profileImage, setProfileImage] = useState<string | undefined>();

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2600); };
  const enterWorkspace = () => { setShowAuth(false); setShowLanding(false); };
  const handleAuthSuccess = (payload: { access: string; refresh: string; user: AuthUser }) => { saveSession(payload); setAuthUser(payload.user); setShowAuth(false); setShowLanding(false); notify(`Welcome to SplitWise+, ${payload.user.display_name}.`); };
  const handleSignOut = () => { clearSession(); setAuthUser(null); setShowLanding(true); setShowAuth(false); notify("You have been signed out."); };
  const navigate = (view: View) => { setActiveView(view); setShowLanding(false); };
  const selectGroup = (group: Group) => { setActiveGroup(group); setShowGroupMenu(false); setActiveView("overview"); notify(`Switched to ${group.name}.`); };
  const activeMessages = conversation.kind === "group" ? chat : (privateChats[conversation.memberId ?? ""] ?? []);

  useEffect(() => {
    if (!getAccessToken()) return;
    api.me().then(setAuthUser).catch(() => { clearSession(); setAuthUser(null); });
  }, []);

  useEffect(() => {
    if (activeView !== "chat") return;
    const handlePayload = (payload: unknown) => {
      const event = payload as Partial<ChatMessage> & { event?: string };
      if (event.event !== "message" || !event.id || !event.message) return;
      const message = event as ChatMessage;
      if (conversation.kind === "group") setChat((current) => current.some((item) => item.id === message.id) ? current : [...current, message]);
      else setPrivateChats((current) => ({ ...current, [conversation.memberId ?? ""]: [...(current[conversation.memberId ?? ""] ?? []).filter((item) => item.id !== message.id), message] }));
    };
    const socket = conversation.kind === "group" ? connectToGroupChat(activeGroup.id, handlePayload) : connectToDirectChat(conversation.memberId ?? "", handlePayload);
    return () => socket.close();
  }, [activeGroup.id, activeView, conversation.kind, conversation.memberId]);

  const addExpense = (expense: Expense) => {
    setExpenses((current) => [expense, ...current]);
    setActivity((current) => [{ id: crypto.randomUUID(), member: "Rafi", initials: "RF", action: "added", target: expense.title, time: "Just now", color: "#b7f36b" }, ...current]);
    setShowExpense(false); navigate("expenses"); notify("Expense saved and balances recalculated in ৳");
  };

  const sendMessage = (message: string, attachments: ChatAttachment[] = [], replyTo?: string) => {
    if (!message.trim() && attachments.length === 0) return;
    const next: ChatMessage = { id: crypto.randomUUID(), senderId: "me", member: "Rafi", initials: "RF", message, time: "Now", color: "#b7f36b", mine: true, attachments, replyTo, read: false };
    if (conversation.kind === "group") setChat((current) => [...current, next]);
    else setPrivateChats((current) => ({ ...current, [conversation.memberId ?? ""]: [...(current[conversation.memberId ?? ""] ?? []), next] }));
    notify(attachments.length ? "Shared to the conversation" : "Message sent");
  };

  const openDirect = (member: Member) => { setConversation({ id: `dm-${member.id}`, kind: "direct", title: member.name, subtitle: member.online ? "Active now" : member.profile.lastSeen ?? "Active recently", memberId: member.id, unread: 0, lastMessage: "Start a private chat", accent: member.color }); };
  const addReaction = (id: string, emoji: string) => {
    const updater = (items: ChatMessage[]) => items.map((item) => item.id !== id ? item : { ...item, reactions: [...(item.reactions ?? []).filter((reaction) => reaction.emoji !== emoji), { emoji, count: ((item.reactions ?? []).find((reaction) => reaction.emoji === emoji)?.count ?? 0) + 1, reacted: true }] });
    if (conversation.kind === "group") setChat(updater); else setPrivateChats((current) => ({ ...current, [conversation.memberId ?? ""]: updater(current[conversation.memberId ?? ""] ?? []) }));
  };

  if (showLanding) return <><Landing onEnter={() => { setAuthMode("signin"); setShowAuth(true); }} onNavigate={navigate} /><button className="demo-entry" onClick={enterWorkspace}>Preview the workspace without an account</button>{showAuth && <AuthModal mode={authMode} onModeChange={setAuthMode} onClose={() => setShowAuth(false)} onSuccess={handleAuthSuccess} onDemo={enterWorkspace} />}</>;
  return <div className={`app-shell ${theme}`}>
    <Sidebar activeView={activeView} onNavigate={navigate} onLanding={() => setShowLanding(true)} activeGroup={activeGroup} groupMenuOpen={showGroupMenu} onToggleGroupMenu={() => setShowGroupMenu((value) => !value)} onGroupChange={selectGroup} onOpenPalette={() => setShowPalette(true)} profileImage={profileImage} onOpenProfile={() => setShowProfile(members[0])} onSignOut={handleSignOut} authUser={authUser} />
    <main className="main-content"><Topbar activeGroup={activeGroup} query={query} setQuery={setQuery} onOpenPalette={() => setShowPalette(true)} onNotifications={() => setShowNotifications((value) => !value)} onTheme={() => setTheme(theme === "dark" ? "light" : "dark")} theme={theme} />
      {showNotifications && <Notifications onClose={() => setShowNotifications(false)} onAction={(message) => { setShowNotifications(false); notify(message); }} />}
      <div className="page-content">
        {activeView === "overview" && <Overview activeGroup={activeGroup} onAddExpense={() => setShowExpense(true)} onNavigate={navigate} expenses={expenses} activity={activity} onToast={notify} />}
        {activeView === "expenses" && <ExpensesPage activeGroup={activeGroup} expenses={expenses} onAddExpense={() => setShowExpense(true)} query={query} onToast={notify} />}
        {activeView === "settle" && <SettlePage activeGroup={activeGroup} onToast={notify} />}
        {activeView === "plan" && <PlanPage activeGroup={activeGroup} onToast={notify} />}
        {activeView === "chat" && <ChatPage activeGroup={activeGroup} conversations={[conversation, ...members.slice(1, 4).map((member) => ({ id: `dm-${member.id}`, kind: "direct" as const, title: member.name, subtitle: member.online ? "Active now" : member.profile.lastSeen ?? "Active recently", memberId: member.id, unread: member.id === "nabil" ? 1 : 0, lastMessage: member.id === "nabil" ? "Bro, I uploaded the ride receipt." : "Start a private chat", accent: member.color }))]} activeConversation={conversation} onSelectConversation={setConversation} chat={activeMessages} onSend={sendMessage} onReact={addReaction} onOpenProfile={(id) => setShowProfile(members.find((member) => member.id === id) ?? null)} onOpenDirect={openDirect} chatTheme={chatTheme} onThemeChange={setChatTheme} />}
      </div>
    </main>
    <div className="mobile-nav">{(["overview", "expenses", "settle", "plan", "chat"] as View[]).map((view) => <button key={view} className={activeView === view ? "active" : ""} onClick={() => navigate(view)}><NavIcon view={view} /><span>{view === "overview" ? "Home" : view === "settle" ? "Settle" : view[0].toUpperCase() + view.slice(1)}</span></button>)}</div>
    {showExpense && <ExpenseModal onClose={() => setShowExpense(false)} onSave={addExpense} />}
    {showPalette && <CommandPalette onClose={() => setShowPalette(false)} onNavigate={navigate} onAddExpense={() => { setShowPalette(false); setShowExpense(true); }} />}
    {showProfile && <ProfileDrawer member={showProfile} avatarUrl={showProfile.id === "me" ? profileImage : undefined} onClose={() => setShowProfile(null)} onMessage={() => { if (showProfile.id !== "me") openDirect(showProfile); setShowProfile(null); navigate("chat"); }} onAvatarChange={(url) => { setProfileImage(url); notify("Profile picture updated"); }} />}
    {toast && <div className="toast"><Check size={16} /> {toast}</div>}
  </div>;
}

function AuthModal({ mode, onModeChange, onClose, onSuccess, onDemo }: { mode: "signin" | "signup"; onModeChange: (mode: "signin" | "signup") => void; onClose: () => void; onSuccess: (payload: { access: string; refresh: string; user: AuthUser }) => void; onDemo: () => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const isSignup = mode === "signup";
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError("");
    if (isSignup && password !== confirm) { setError("Passwords do not match."); return; }
    setBusy(true);
    try {
      const payload = isSignup ? await api.signup({ username, password, password_confirm: confirm, first_name: firstName, last_name: lastName, email }) : await api.signin({ username, password });
      onSuccess(payload);
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : "We could not complete that request.");
    } finally { setBusy(false); }
  };
  return <div className="auth-backdrop" onClick={onClose}><section className="auth-modal" onClick={(event) => event.stopPropagation()}><button className="auth-close icon-button" onClick={onClose} aria-label="Close authentication"><X size={17} /></button><div className="auth-mark"><Split size={19} /></div><span className="muted-label">SPLITWISE+ ACCOUNT</span><h2>{isSignup ? "Start sharing smarter." : "Welcome back to your workspace."}</h2><p className="auth-subtitle">{isSignup ? "Create your account and bring every shared ৳ decision into context." : "Sign in to continue to your groups, balances, and conversations."}</p><div className="auth-tabs"><button type="button" className={!isSignup ? "active" : ""} onClick={() => onModeChange("signin")}>Sign in</button><button type="button" className={isSignup ? "active" : ""} onClick={() => onModeChange("signup")}>Create account</button></div><form onSubmit={submit}>{isSignup && <div className="auth-grid"><label>First name<input value={firstName} onChange={(event) => setFirstName(event.target.value)} placeholder="Rafi" required /></label><label>Last name<input value={lastName} onChange={(event) => setLastName(event.target.value)} placeholder="Hasan" required /></label></div>}<label>Username<input value={username} onChange={(event) => setUsername(event.target.value)} placeholder="rafi_bd" autoComplete="username" required /></label>{isSignup && <label>Email <span className="optional">optional</span><input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" autoComplete="email" /></label>}<label>Password<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="At least 8 characters" autoComplete={isSignup ? "new-password" : "current-password"} minLength={8} required /></label>{isSignup && <label>Confirm password<input type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} placeholder="Repeat your password" autoComplete="new-password" required /></label>}{error && <div className="auth-error"><CircleDollarSign size={15} />{error}</div>}<button className="primary-button auth-submit" disabled={busy}>{busy ? "Connecting…" : isSignup ? "Create my account" : "Sign in to SplitWise+"}<ArrowUpRight size={15} /></button></form><button className="demo-link" onClick={onDemo}>Preview the workspace without an account</button><div className="auth-footnote"><Check size={13} /> BDT-first workspace · secure JWT session</div></section></div>;
}

